import sys
input = sys.stdin.readline

def main():
    n = int(input())
    heights = list(map(int, input().split()))

    while True:
        changed = False
        for j in range(n - 1):
            if heights[j] + 2 <= heights[j + 1]:
                change = (heights[j + 1] - heights[j]) // 2
                heights[j] += change
                heights[j + 1] -= change
                changed = True
        if not changed:
            break

    print(' '.join(map(str, heights)))

if __name__ == "__main__":
    main()
